// Generic recipe-driven model (universal C++ engine, milestone M1/M2).
//
// A model is a recipe (JSON, generated by `veystrix models inspect
// --emit-recipe`) interpreted over a registry of blocks:
//
//   mixers:  "linear.gdn"      gated delta net (mlx_lm qwen3_5 GatedDeltaNet)
//            "attn.gated_gqa"  GQA attention, optional QK RMSNorm, optional
//                              sigmoid output gate (q_proj outputs 2x), partial
//                              rotary; KV via the tiered KVStore
//   mlps:    "moe.softmax_topk" softmax router, top-k, optional renorm, SwiGLU
//                              stacked experts (streamed or resident), optional
//                              shared expert with sigmoid gate
//            "mlp.swiglu"      dense gated MLP
//   norms:   RMSNorm (optional mlx_lm "+1" shift at load)
//   embed / head: quantized or dense, tied or not
//
// Every block mirrors the mlx_lm module op-for-op (same MLX ops, same compiled
// elementwise functions), so on the same MLX build the outputs are bitwise
// equal to mlx_lm (gated by `veystrix models port-check`).
//
// Forward works on "lanes": each lane is one session's tokens [1, S] with its
// own per-layer state. Decode batches several S=1 lanes; prefill runs one lane
// with S tokens. Per-lane arithmetic is identical to a solo call; lanes only
// share the routed-expert reads (union of the wanted experts per layer).
#pragma once

#include <cstdint>
#include <functional>
#include <map>
#include <memory>
#include <optional>
#include <string>
#include <utility>
#include <vector>

#include <mlx/mlx.h>

#include "generic/expert_stream.hpp"
#include "generic/json_lite.hpp"
#include "generic/kv_store.hpp"
#include "generic/st_index.hpp"

namespace veystrix::engine::generic {

namespace mx = mlx::core;
using NamedArrays = std::vector<std::pair<std::string, mx::array>>;

// ---- weights ---------------------------------------------------------------
struct QuantSpec {
  bool quantized = false;
  int group_size = 64;
  int bits = 4;
  std::string mode = "affine";
};

struct QLinear {
  std::optional<mx::array> w, scales, biases, bias;
  QuantSpec q;
  mx::array operator()(const mx::array& x) const;
  int64_t nbytes() const;
};

struct QEmbedding {
  std::optional<mx::array> w, scales, biases;
  QuantSpec q;
  mx::array operator()(const mx::array& ids) const;      // [B,S] -> [B,S,H]
  mx::array as_linear(const mx::array& x) const;         // tied head
};

// Loader context handed to block factories.
class Loader {
 public:
  Loader(const StIndex& idx, const Json& recipe);
  const StIndex& index() const { return idx_; }
  const Json& recipe() const { return recipe_; }
  QuantSpec quant_for(const std::string& module_path) const;
  QLinear linear(const std::string& module_path) const;
  QEmbedding embedding(const std::string& module_path) const;
  mx::array tensor(const std::string& name) const;   // loaded (lazy-free) array
  mx::array norm_weight(const std::string& module_path, bool shift) const;
  bool has(const std::string& name) const { return idx_.has(name); }
  static std::string expand(const std::string& tmpl, int layer);
 private:
  const StIndex& idx_;
  const Json& recipe_;
};

// ---- state -----------------------------------------------------------------
struct LayerState {
  std::vector<mx::array> arrays;  // block-defined slots (GDN: conv, recurrent)
  std::vector<mx::array> pre;     // pre-layer block slots (PLE: n-gram context, conv state)
  std::optional<KVStore> kv;      // attention blocks
  int64_t tokens = 0;
  bool save_conv_history = false; // speculative verify: keep [B, hist+S, C] for exact rollback
};
using SessionState = std::vector<LayerState>;

// ---- blocks ----------------------------------------------------------------
class Mixer {
 public:
  virtual ~Mixer() = default;
  virtual std::string type() const = 0;
  virtual void reset(LayerState& st) const = 0;
  virtual mx::array forward(const mx::array& x, LayerState& st) const = 0;  // [1,S,H]
  virtual mx::array forward_qkv(const mx::array& xq, const mx::array& /*xk*/, const mx::array& /*xv*/,
                                LayerState& st) const {
    return forward(xq, st);
  }
  virtual NamedArrays save(const LayerState& st, const std::string& pfx) const = 0;
  virtual void load(LayerState& st, const std::string& pfx, const NamedArrays& a,
                    int64_t tokens) const = 0;
  virtual int64_t kv_values_per_token() const { return 0; }  // K+V elements per token
  virtual int64_t sliding_window() const { return 0; }
  virtual int64_t weight_bytes() const = 0;
};

struct MlpStats {
  int64_t expert_bytes = 0;
  int distinct_experts = 0;
  double route_sync_ms = 0, read_ms = 0;
};

class Mlp {
 public:
  virtual ~Mlp() = default;
  virtual std::string type() const = 0;
  // One output per lane; lanes are processed together so expert reads are shared.
  virtual std::vector<mx::array> forward(const std::vector<mx::array>& xs, MlpStats& stats) const = 0;
  virtual void prefetch_hint() const {}  // page-cache read-ahead (next layer, prefill)
  // The next layer's MLP (nullptr for the last), for next-layer expert guesses in decode.
  virtual void link_next(const Mlp* /*next*/) {}
  // Prefill: start reading this layer's experts for a chunk of `tokens` tokens in the
  // background (called while the previous layer computes). Returns false if not used.
  virtual bool prefill_prefetch_wanted(int /*tokens*/) const { return false; }
  virtual void prefill_prefetch(int /*tokens*/) const {}
  // Trigger speculative prefetch of the next streamed layer from a resident boundary layer.
  virtual void spec_prefetch_next(const mx::array& /*x*/) const {}
  // Looped-model optimization: at the end of Loop Pass 1, predict & warm all streamed epilogue
  // layers' experts into the OS page cache in parallel with Loop Pass 2's GPU compute.
  virtual void prefetch_epilogue_from_loop(const mx::array& /*x*/,
                                           const std::vector<const Mlp*>& /*targets*/) const {}
  virtual bool is_resident() const { return false; }
  virtual void load_resident() {}
  virtual void release_resident() {}
  virtual int64_t weight_bytes() const = 0;
  virtual int64_t streamed_bytes() const { return 0; }
};

// A block applied to the residual streams before a layer (Qwen4 PLE): h += forward(h, ids).
// It sees the lane's token ids, which mixers and MLPs never do.
class PreBlock {
 public:
  virtual ~PreBlock() = default;
  virtual std::string type() const = 0;
  virtual mx::array forward(const mx::array& h, const std::vector<int32_t>& ids, LayerState& st) const = 0;
  virtual int64_t weight_bytes() const = 0;
};

struct BlockCtx {
  const Loader& loader;
  const Json& params;  // block definition from recipe "blocks"
  int layer;
  bool resident_experts;
  const KVPolicy* kv;  // attention blocks
};
using MixerFactory = std::function<std::unique_ptr<Mixer>(const BlockCtx&)>;
using MlpFactory = std::function<std::unique_ptr<Mlp>(const BlockCtx&)>;
using PreFactory = std::function<std::unique_ptr<PreBlock>(const BlockCtx&)>;
std::map<std::string, MixerFactory>& mixer_registry();
std::map<std::string, MlpFactory>& mlp_registry();
std::map<std::string, PreFactory>& pre_registry();
std::vector<std::string> registered_blocks();

// ---- model -----------------------------------------------------------------
class Inkling2DSpark;

struct ModelOptions {
  bool resident_experts = false;
  bool enable_dspark = false;
  KVPolicy kv;  // applied to every attention block unless the recipe overrides per layer
};

struct ForwardStats {
  int64_t expert_bytes = 0;
  double route_sync_ms = 0, read_ms = 0;
};

struct VerifyResult {
  mx::array logits = mx::array(0.0f);  // [1, V] if !all_logits else [S, V]
  std::optional<mx::array> features;   // [S, T, H] BF16 when DSpark is active
};

class GenericModel {
 public:
  GenericModel(const std::string& model_dir, const std::string& recipe_json, const ModelOptions& opt);
  ~GenericModel();

  int n_layers() const { return static_cast<int>(mixers_.size()); }
  int n_visits() const { return static_cast<int>(visit_layer_.size()); }
  int vocab() const { return vocab_; }
  int unpadded_vocab() const { return unpadded_vocab_; }
  float final_logit_softcap() const { return final_logit_softcap_; }
  int hidden() const { return hidden_; }
  const std::string& model_type() const { return model_type_; }
  const std::string& recipe_digest() const { return recipe_digest_; }
  const KVPolicy& kv_policy() const { return opt_.kv; }
  int64_t kv_values_per_token() const;
  int64_t resident_bytes() const { return resident_bytes_; }
  int64_t streamed_bytes() const;
  bool resident_experts() const { return opt_.resident_experts || streamed_bytes() == 0; }
  bool is_looped() const { return looped_; }
  int loop_core_start() const { return loop_core_start_; }
  int loop_core_end() const { return loop_core_end_; }
  int loop_passes() const { return loop_passes_; }
  const Inkling2DSpark* dspark() const { return dspark_.get(); }
  mx::array embed_normalized(const mx::array& ids) const;
  mx::array lm_head_raw(const mx::array& x) const;
  std::string describe_blocks() const;

  // Exact prefix truncation of SessionState
  bool truncate(SessionState& st, int64_t target_tokens) const;

  // Stage-Major prefill for looped MoE (Inkling 2 Mini):
  // Reads streamed prelude/epilogue layers ONCE from NVMe while looping core layers in RAM.
  VerifyResult prefill_stage_major(const std::vector<int32_t>& tokens, SessionState& state,
                                   ForwardStats* stats = nullptr,
                                   const std::function<bool()>& cancel_check = nullptr);

  void reset(SessionState& st) const;

  // Lanes: tokens per lane ([S_i] ids) and that lane's state. Returns the
  // logits of the LAST position of each lane, shape [1, V] (lazy).
  std::vector<mx::array> forward(const std::vector<std::vector<int32_t>>& tokens,
                                 const std::vector<SessionState*>& states,
                                 ForwardStats* stats = nullptr, bool prefetch_next_layer = false);

  // Single-lane forward with optional all-position logits, DSpark target feature capture,
  // and full conv-history retention for exact post-verify rollback.
  VerifyResult forward_with_features(const std::vector<int32_t>& tokens, SessionState& state,
                                     bool all_logits, bool save_verify_history,
                                     ForwardStats* stats = nullptr, bool prefetch_next_layer = false);
  bool trim_verify_state(SessionState& st, int64_t old_n, int keep, int total_verify) const;

  NamedArrays save(const SessionState& st) const;
  void load(SessionState& st, const NamedArrays& a, int64_t tokens) const;

 private:
  ModelOptions opt_;
  std::unique_ptr<StIndex> idx_;
  Json recipe_;
  std::string model_type_, recipe_digest_;
  int vocab_ = 0, hidden_ = 0;
  float eps_ = 1e-6f;
  QEmbedding embed_;
  mx::array final_norm_ = mx::array(0.0f);
  std::optional<QLinear> head_;
  bool tied_ = false;
  std::vector<mx::array> in_norm_, post_norm_;
  // Hyper-connection residual (recipe "residual": {"type": "hyper"}): the hidden state is
  // hc_count streams [1, S, hc*H]; each layer mixes them into one input per branch and
  // injects the branch output back with learned weights (Qwen4ExpGatedResidual).
  struct HyperRes {
    mx::array norm = mx::array(0.0f);
    QLinear down, up;
    std::optional<QLinear> inject;
  };
  bool hyper_ = false;
  int hc_ = 1;
  bool hc_one_centered_ = true;
  std::vector<HyperRes> attn_hc_, mlp_hc_;
  std::optional<HyperRes> final_hc_;
  struct LoopGate {
    mx::array msg_query = mx::array(0.0f);   // F32 [4, H]
    mx::array down = mx::array(0.0f);        // F32 [4, 2, H, rank]
    mx::array gain_forget = mx::array(0.0f); // F32 [4, rank, 2*H]
    std::vector<mx::array> mq_s;  // [4] x [1, 1, 1, H] (scaled by hidden**-0.5)
    std::vector<mx::array> w0;    // [4] x [H, rank]
    std::vector<mx::array> w1;    // [4] x [H, rank]
    std::vector<mx::array> wgf;   // [4] x [rank, 2*H]
    mx::array mq_qkv_t = mx::array(0.0f);  // F32 [H, 3] for batched Q/K/V message read
    mx::array w0_qkv = mx::array(0.0f);    // BF16 [H, 3*rank] for batched Q/K/V x_rms projection
    mx::array w1_qkv = mx::array(0.0f);    // BF16 [3, H, rank] for batched Q/K/V m_rms projection
    mx::array wgf_qkv = mx::array(0.0f);   // BF16 [3, rank, 2*H] for batched Q/K/V gain/forget
  };
  bool block_attn_res_ = false;
  int res_block_size_ = 6;
  bool res_norm_values_ = true;
  std::optional<mx::array> embed_norm_;
  std::optional<mx::array> final_res_query_;
  std::vector<std::optional<mx::array>> attn_res_q_, mlp_res_q_;
  std::vector<std::optional<mx::array>> attn_sconv_, mlp_sconv_;
  std::vector<std::optional<mx::array>> q_in_norm_, k_in_norm_, v_in_norm_;
  float final_logit_softcap_ = 0.0f;
  int unpadded_vocab_ = 0;
  bool looped_ = false;
  int loop_core_start_ = 0, loop_core_end_ = 0, loop_passes_ = 1, loop_gate_rank_ = 64;
  bool loop_share_kv_ = false;
  std::vector<int> visit_layer_;
  std::vector<int> visit_pass_;
  std::vector<std::optional<LoopGate>> loop_gates_;
  std::vector<std::unique_ptr<PreBlock>> pre_;  // per layer, null when the layer has none
  std::pair<mx::array, mx::array> hyper_mix(const mx::array& h, const HyperRes& r) const;
  mx::array hyper_final(const mx::array& h) const;
  mx::array attn_res_mix(const mx::array& bank_stacked, const std::optional<mx::array>& partial,
                         const mx::array& query) const;
  std::vector<mx::array> attn_res_mix_multi(const mx::array& bank_stacked,
                                            const std::optional<mx::array>& partial,
                                            const mx::array& queries_qh) const;
  mx::array apply_loop_msg(const mx::array& x, const mx::array& prev_sn, const mx::array& prev_vals,
                           const LoopGate& g, int target_idx,
                           const std::optional<mx::array>& x_rms_cached = std::nullopt) const;
  std::vector<mx::array> apply_loop_msg_qkv_shared(const mx::array& mix, const mx::array& prev_sn,
                                                   const LoopGate& g) const;
  std::vector<mx::array> forward_inkling(const std::vector<mx::array>& h,
                                         const std::vector<SessionState*>& states,
                                         ForwardStats* stats, bool prefetch_next_layer,
                                         bool all_logits, bool capture_features,
                                         bool save_verify_history,
                                         std::optional<mx::array>* out_features);
  std::vector<std::unique_ptr<Mixer>> mixers_;
  std::vector<std::unique_ptr<Mlp>> mlps_;
  std::unique_ptr<Inkling2DSpark> dspark_;
  int64_t resident_bytes_ = 0;
};

}  // namespace veystrix::engine::generic
